entries[102346] = { ["name"] = "Schneller Waldschreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbaren schnellen Waldschreiter oder gibt ihn wieder frei.\n\"Diese farbenfrohe Rasse findet man nur in den Wäldern der Dunkelmond-Insel.\"\nVerkäufer:\nLhara\nZone:\nDunkelmond-Insel\nKosten:\n180" }
entries[102349] = { ["name"] = "Schneller Frühlingsschreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbaren schnellen Frühlingsschreiter oder gibt ihn wieder frei.\n\"Die Freuden des Nobelgartenfests kann man am besten genießen, wenn man diese treue, liebe und langweilig gefärbte Laune der Natur bei sich hat.\"\nVerkäufer:\nNobelgartenhändler\nZone:\nDurotar, Immersangwald, Mulgore, Tirisfal, Azurmythosinsel,\nDun Morogh, Wald von Elwynn, Teldrassil\nKosten:\n500" }
entries[102350] = { ["name"] = "Schneller Blumenstrauß", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbaren schnellen Blumenstrauß oder gibt ihn wieder frei.\n\"Wolle Rose kaufe?\"\nWeltereignis:\nLiebe liegt in der Luft\n\nVerkäufer:\nReizende Verkäuferin (Allianz)\nZone:\nSturmwind\nKosten:\n270\n\nVerkäufer:\nReizende Verkäuferin (Horde)\nZone:\nOrgrimmar\nKosten:\n270" }
